inline std::vector<unsigned char> retail(u32 va,std::size_t n) {
 for(const auto& g:guards)if(va>=g.bytes.va&&va-g.bytes.va+n<=g.bytes.hex.size()/2) {
  std::vector<unsigned char> b(n);for(std::size_t i=0;i<n;++i)b[i]=limits_rules::hex_byte(g.bytes.hex,i+va-g.bytes.va);return b;
 }
 return {};
}
struct targets {const void *jump,*fly,*colossus_input,*colossus_contact,*bounce,*fastball;};
inline std::vector<xml1_hook_transaction::patch> patches(u32 mask,const targets& t) {
 std::vector<xml1_hook_transaction::patch> out;
 auto write=[&](u32 a,std::vector<unsigned char> b){out.push_back({a,retail(a,b.size()),std::move(b)});};
 auto jump=[&](u32 a,const void* b,std::size_t n){write(a,branch(a,b,n));};
 auto nop=[&](u32 a,std::size_t n){write(a,std::vector<unsigned char>(n,0x90));};
 if(mask&jump_damage)jump(0x4ee99b,t.jump,5);
 if(mask&fly_damage)jump(0x4eeb88,t.fly,5);
 if(mask&colossus) {jump(0x4eced0,t.colossus_input,5);jump(0x4ed220,t.colossus_contact,8);}
 if(mask&bounce)jump(0x4ed1a0,t.bounce,6);
 if(mask&fastball)jump(0x4f4adf,t.fastball,7);
 if(mask&idle) {
  // Keep rule 18's stun ownership path. Only the source idle/bored policy
  // gates change here; no stun flag or reaction service is replaced.
  write(0x4ee07d,{0x3c});write(0x4ee1b5,{0x3c});write(0x4ee39e,{0x3c});
  nop(0x4ee094,0x21);nop(0x4ee1d0,0x29);nop(0x4ee230,16);
  jump(0x4ee2e2,reinterpret_cast<void*>(0x4ee338),7);
 }
 if(mask&scale)nop(0x4f01d4,12);
 if(mask&phase)nop(0x4f026a,4);
 if(mask&visibility) {
  jump(0x4efc7e,reinterpret_cast<void*>(0x4efc89),7);
  jump(0x4f44a4,reinterpret_cast<void*>(0x4f44af),7);
 }
 return out;
}
